{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/seen-2/play/users/u064/system/state/workspace/programs/task-d0f4c17f.py",
 "content": "def transform(grid):
    # Each diagonal signal (constant r+c) is painted uniformly from its
    # observed color. The 6/9/8 sequence repeats every three diagonals;
    # the 5-marked diagonal is the fourth phase, alternating with 6.
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            s = r + c
            if s < 4:
                row.append(0)
            elif s < 9:
                row.append((6, 9, 8)[(s - 4) % 3])
            else:
                row.append((5, 6, 5)[(s - 9) % 3])
        out.append(row)
    return out
