 "content": "def transform(grid):
    # Find colored diagonals of constant (column-row). Their colors define a
    # periodic diagonal coloring; infer the period as the smallest one that
    # assigns each observed diagonal class consistently.
    h, w = len(grid), len(grid[0])
    diagonal = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                diagonal[c-r] = grid[r][c]
    period = next(p for p in range(1, h+w+1)
                  if all((a-b) % p != 0 or va == vb
                         for a, va in diagonal.items()
                         for b, vb in diagonal.items()))
    palette = {d % period: v for d, v in diagonal.items()}
    # Require an observed color for every residue; if not, fill nearest class.
    for k in range(period):
        if k not in palette:
            nearest = min(palette, key=lambda q: (min((k-q)%period,(q-k)%period), q))
            palette[k] = palette[nearest]
    return [[palette[(c-r)%period] for c in range(w)] for r in range(h)]
"
}

