    # Use the parallel diagonal tracks' recurring colors; extend the visible
    # 6-9-8 stripe rightward and the 5 track down-left, leaving other cells 0.
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    for r in range(h):
        starts=[c for c,v in enumerate(grid[r]) if v==6]
        if starts:
            c0=min(starts)
            for c in range(c0,w):
                out[r][c]=(6,9,8)[(c-c0)%3]
    for c in range(w):
        starts=[r for r in range(h) if grid[r][c]==5]
        if starts:
            r0=min(starts)
            for r in range(r0,h):
                if out[r][c]==0: out[r][c]=5
    return out
